#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterString: FfiConverter {
    typealias SwiftType = String
    typealias FfiType = RustBuffer

    public static func lift(_ value: RustBuffer) throws -> String {
        defer {
            value.deallocate()
        }
        if value.data == nil {
            return String()
        }
        let bytes = UnsafeBufferPointer<UInt8>(start: value.data!, count: Int(value.len))
        // Use Swift's native UTF-8 decoder; `String(bytes:encoding:.utf8)` goes
        // through Foundation's NSString and silently strips a leading U+FEFF BOM.
        // Invalid UTF-8 substitutes U+FFFD instead of trapping (unreachable
        // given Rust's `String` invariant).
        return String(decoding: bytes, as: UTF8.self)
    }

    public static func lower(_ value: String) -> RustBuffer {
        return value.utf8CString.withUnsafeBufferPointer { ptr in
            // The swift string gives us int8_t, we want uint8_t.
            ptr.withMemoryRebound(to: UInt8.self) { ptr in
                // The swift string gives us a trailing null byte, we don't want it.
                let buf = UnsafeBufferPointer(rebasing: ptr.prefix(upTo: ptr.count - 1))
                return RustBuffer.from(buf)
            }
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> String {
        let len: Int32 = try readInt(&buf)
        // See `lift` above for why we avoid Foundation's NSString-backed decoder here.
        return String(decoding: try readBytes(&buf, count: Int(len)), as: UTF8.self)
    }

    public static func write(_ value: String, into buf: inout [UInt8]) {
        let len = Int32(value.utf8.count)
        writeInt(&buf, len)
        writeBytes(&buf, value.utf8)
    }
}




/**
 * Handle to an open livtet library (SQLite database + search index).
 */
public protocol LivtetStoreProtocol: AnyObject, Sendable {
    
    /**
     * Aggregate library and reading-activity statistics.
     */
    func getDashboardStats() async throws  -> DashboardStats
    
    /**
     * The most recent search-history entries, newest first.
     *
     * Nothing in the core writes `search_history` yet, so this returns
     * whatever rows already exist (seeded or manually inserted).
     */
    func getRecentSearches(limit: UInt32) async throws  -> [RecentSearch]
    
    /**
     * Works with recorded reading progress, most recently read first.
     *
     * `last_read_at` is the start of the most recent reading session
     * for the edition, falling back to when progress was first
     * recorded. `limit` is clamped to at least one.
     */
    func getRecentlyReadBooks(limit: UInt32) async throws  -> [RecentlyReadBook]
    
    /**
     * Number of works matching `filters` (ignores `limit`/`offset`).
     */
    func countWorksFiltered(filters: WorkFilters) async throws  -> UInt64
    
    /**
     * Formats attached to at least one edition, ordered by name.
     */
    func listFormats() async throws  -> [FormatInfo]
    
    /**
     * Languages used by at least one edition, ordered by name.
     */
    func listLanguages() async throws  -> [LibraryLanguage]
    
    /**
     * Works matching `filters`, ordered and paginated.
     *
     * Only `format_ids`, `language_ids`, `sort_by`, `sort_direction`,
     * and `limit` are honoured; any other filter dimension fails closed
     * with `InvalidInput` rather than silently returning unfiltered
     * results.
     */
    func listWorksFiltered(filters: WorkFilters, offset: UInt32) async throws  -> [WorkSummary]
    
    /**
     * Rebuild the whole search index from the database. Pass a
     * listener to receive [`ReindexProgressEvent`]s.
     */
    func reindex(progress: ReindexProgress?) async throws 
    
    /**
     * Wipe the library content (keeping schema and reference
     * dictionaries), seed `num_works` works, and rebuild the search
     * index. Intended for smoke tests and demo data, not production
     * flows.
     */
    func resetAndSeed(numWorks: UInt32) async throws  -> SeedStats
    
    /**
     * Seed sample data (idempotent: a second call with the same
     * arguments reports `works_created: 0`).
     */
    func seedSampleData(numWorks: UInt32) async throws  -> SeedStats
    
    /**
     * Attach an identifier to an edition. Idempotent per (edition,
     * URN): existing rows are reused, so duplicate calls do not
     * create duplicate junctions. Fails `NotFound` for a missing
     * edition, `InvalidInput` bubbles up from the lifted
     * [`Identifier`] URN at the FFI boundary.
     */
    func addEditionIdentifier(editionId: DbId, identifier: Identifier) async throws  -> String
    
    /**
     * Detach the digital file by deleting the edition's
     * `digital_inventory` row. Returns `false` when the edition had
     * no file (or does not exist).
     */
    func removeEditionFile(editionId: DbId) async throws  -> Bool
    
    /**
     * Attach (or replace) the digital file of an edition. Creates the
     * 1:1 `digital_inventory` row on first use. Fails `NotFound`
     * when the edition does not exist.
     */
    func setEditionFile(editionId: DbId, filePath: DiskPath, fileFormat: String?, fileSizeBytes: Int64?) async throws 
    
    /**
     * Apply a [`EditionPatch`] and return the refreshed detail.
     */
    func updateEdition(editionId: DbId, patch: EditionPatch) async throws  -> EditionDetail
    
    /**
     * Add an annotation (note/highlight) to an edition.
     */
    func addAnnotation(editionId: DbId, content: String, location: String?) async throws  -> Annotation
    
    /**
     * Append an edition to a reading list (position = end). No-op for
     * a duplicate membership; fails `NotFound` for a missing list.
     */
    func addEditionToList(listId: DbId, editionId: DbId) async throws 
    
    /**
     * Create an empty reading list.
     */
    func createReadingList(name: String, description: String?) async throws  -> ReadingList
    
    /**
     * Delete one annotation. `false` when it did not exist.
     */
    func deleteAnnotation(id: DbId) async throws  -> Bool
    
    /**
     * Delete a reading list and its memberships. `false` when absent.
     */
    func deleteReadingList(listId: DbId) async throws  -> Bool
    
    /**
     * The progress row for an edition, if any.
     */
    func getReadingProgress(editionId: DbId) async throws  -> ReadingProgress?
    
    /**
     * The reading status of a work, or `None` when never set.
     */
    func getWorkStatus(workId: DbId) async throws  -> WorkStatus?
    
    /**
     * All annotations for an edition, oldest first.
     */
    func listAnnotations(editionId: DbId) async throws  -> [Annotation]
    
    /**
     * All reading lists, each with its edition ids in position order.
     */
    func listReadingLists() async throws  -> [ReadingList]
    
    /**
     * Record progress for an edition. Upserts the edition's progress
     * row: `additional_seconds` accumulates into the total reading
     * time, the rest replaces.
     */
    func recordReadingProgress(editionId: DbId, formatId: DbId, progress: Double, unit: ProgressUnit?, lastLocation: String?, additionalSeconds: Int64) async throws  -> ReadingProgress
    
    /**
     * Record one finished reading session.
     */
    func recordReadingSession(input: ReadingSessionInput) async throws  -> ReadingSession
    
    /**
     * Remove an edition from a reading list. `false` when not a member.
     */
    func removeEditionFromList(listId: DbId, editionId: DbId) async throws  -> Bool
    
    /**
     * Set the reading status of a work (insert-or-replace).
     */
    func setWorkStatus(workId: DbId, status: WorkStatus) async throws 
    
    /**
