/**
 * Foreign-side progress listener for [`LivtetStore::reindex`].
 * Implementations live in Kotlin/Swift and are called on a worker
 * coroutine/thread — they must dispatch to the UI thread themselves.
 */
public protocol ReindexProgress: AnyObject, Sendable {
    
    func onEvent(event: ReindexProgressEvent) 
    
}
/**
 * Foreign-side progress listener for [`LivtetStore::reindex`].
 * Implementations live in Kotlin/Swift and are called on a worker
 * coroutine/thread — they must dispatch to the UI thread themselves.
 */
open class ReindexProgressImpl: ReindexProgress, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_livtet_ffi_fn_clone_reindexprogress(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_livtet_ffi_fn_free_reindexprogress(handle, $0) }
    }

    

    
open func onEvent(event: ReindexProgressEvent)  {try! rustCall() {
        uniffiCallStatus in
    uniffi_livtet_ffi_fn_method_reindexprogress_on_event(
            self.uniffiCloneHandle(),
        FfiConverterTypeReindexProgressEvent_lower(event),uniffiCallStatus
    )
}
}
    

    
}



// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceReindexProgress {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceReindexProgress = UniffiVTableCallbackInterfaceReindexProgress(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeReindexProgress.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface ReindexProgress: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeReindexProgress.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface ReindexProgress: handle missing in uniffiClone")
            }
        },
        onEvent: { (
            uniffiHandle: UInt64,
            event: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeReindexProgress.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onEvent(
                     event: try FfiConverterTypeReindexProgressEvent_lift(event)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceReindexProgress> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceReindexProgress>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitReindexProgress() {
    uniffi_livtet_ffi_fn_init_callback_vtable_reindexprogress(UniffiCallbackInterfaceReindexProgress.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReindexProgress: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<ReindexProgress>()

    typealias FfiType = UInt64
    typealias SwiftType = ReindexProgress

    public static func lift(_ handle: UInt64) throws -> ReindexProgress {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ReindexProgressImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: ReindexProgress) -> UInt64 {
         if let rustImpl = value as? ReindexProgressImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ReindexProgress {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ReindexProgress, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


