/**
 * Errors surfaced to Kotlin/Swift consumers.
 */
public 
enum LivtetError: Swift.Error, Equatable, Hashable, Codable, Foundation.LocalizedError {

    
    
    /**
     * A SeaORM / sqlx database failure. See
     * [`ConstraintViolation`](livtet_core::data::ConstraintViolation) for how
     * these messages are produced.
     */
    case Database(String
    )
    /**
     * A Tantivy / search-index failure.
     */
    case Search(String
    )
    /**
     * The referenced entity does not exist.
     */
    case NotFound(entity: String, id: String
    )
    /**
     * Caller-supplied input failed validation (malformed ISBNs,
     * URN strings, enum names, ...).
     */
    case InvalidInput(String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension LivtetError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLivtetError: FfiConverterRustBuffer {
    typealias SwiftType = LivtetError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LivtetError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Database(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .Search(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotFound(
            entity: try FfiConverterString.read(from: &buf), 
            id: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InvalidInput(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LivtetError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Database(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Search(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .NotFound(entity,id):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(entity, into: &buf)
            FfiConverterString.write(id, into: &buf)
            
        
        case let .InvalidInput(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLivtetError_lift(_ buf: RustBuffer) throws -> LivtetError {
    return try FfiConverterTypeLivtetError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLivtetError_lower(_ value: LivtetError) -> RustBuffer {
    return FfiConverterTypeLivtetError.lower(value)
}


/**
 * Progress event during [`LivtetStore::reindex`], mirroring
 * [`livtet_core::search::ReindexEvent`].
 */

public enum ReindexProgressEvent: Equatable, Hashable, Codable {
    
    /**
     * Index loaded; DB rows are being read.
     */
    case loading
    /**
     * A batch was committed; `done`/`total` are document counts.
     */
    case indexing(done: UInt64, total: UInt64
    )





}

#if compiler(>=6)
extension ReindexProgressEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReindexProgressEvent: FfiConverterRustBuffer {
    typealias SwiftType = ReindexProgressEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ReindexProgressEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .loading
        
        case 2: return .indexing(done: try FfiConverterUInt64.read(from: &buf), total: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ReindexProgressEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .loading:
            writeInt(&buf, Int32(1))
        
        
        case let .indexing(done,total):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(done, into: &buf)
            FfiConverterUInt64.write(total, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeReindexProgressEvent_lift(_ buf: RustBuffer) throws -> ReindexProgressEvent {
    return try FfiConverterTypeReindexProgressEvent.lift(buf)
}

